#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef float v4 __attribute__((vector_size(16)));

#define MR 6
#define NR 16
#define KC 256
#define MCHUNK 48

static inline v4 ld(const float *p) { v4 v; memcpy(&v, p, 16); return v; }
static inline void st(float *p, v4 v) { memcpy(p, &v, 16); }

/* C[0..mr) x [0..nc) (+)= rows of A (k range kc) * packed panel Bp */
static void kernel(const float *A, int lda, int mr, const float *Bp,
                   float *C, int ldc, int kc, int first, int nc)
{
    const float *a[MR];
    for (int r = 0; r < MR; r++) a[r] = A + (size_t)(r < mr ? r : 0) * lda;
    v4 c[MR][4];
    for (int r = 0; r < MR; r++)
        for (int j = 0; j < 4; j++) c[r][j] = (v4){0, 0, 0, 0};
    for (int k = 0; k < kc; k++) {
        const float *b = Bp + (size_t)k * NR;
        v4 b0 = ld(b), b1 = ld(b + 4), b2 = ld(b + 8), b3 = ld(b + 12);
        for (int r = 0; r < MR; r++) {
            float s = a[r][k];
            c[r][0] += s * b0; c[r][1] += s * b1;
            c[r][2] += s * b2; c[r][3] += s * b3;
        }
    }
    if (nc == NR) {
        for (int r = 0; r < mr; r++) {
            float *cp = C + (size_t)r * ldc;
            for (int j = 0; j < 4; j++) {
                if (first) st(cp + 4 * j, c[r][j]);
                else st(cp + 4 * j, ld(cp + 4 * j) + c[r][j]);
            }
        }
    } else {
        float tmp[NR];
        for (int r = 0; r < mr; r++) {
            float *cp = C + (size_t)r * ldc;
            for (int j = 0; j < 4; j++) st(tmp + 4 * j, c[r][j]);
            for (int j = 0; j < nc; j++) cp[j] = first ? tmp[j] : cp[j] + tmp[j];
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C, *Bp;
    int n, npanels, nchunks;
    int next_pack, next_chunk;
} job_t;

/* Bp layout: panel p occupies n*NR floats, row k at offset k*NR */
static void pack_panel(job_t *J, int p)
{
    int n = J->n, j0 = p * NR, nc = n - j0 < NR ? n - j0 : NR;
    float *dst = J->Bp + (size_t)p * n * NR;
    for (int k = 0; k < n; k++) {
        const float *src = J->B + (size_t)k * n + j0;
        float *d = dst + (size_t)k * NR;
        if (nc == NR) memcpy(d, src, NR * sizeof(float));
        else {
            int j = 0;
            for (; j < nc; j++) d[j] = src[j];
            for (; j < NR; j++) d[j] = 0.0f;
        }
    }
}

static void do_chunk(job_t *J, int ch)
{
    int n = J->n, i0 = ch * MCHUNK, i1 = i0 + MCHUNK < n ? i0 + MCHUNK : n;
    for (int k0 = 0; k0 < n; k0 += KC) {
        int kc = n - k0 < KC ? n - k0 : KC;
        for (int p = 0; p < J->npanels; p++) {
            int j0 = p * NR, nc = n - j0 < NR ? n - j0 : NR;
            const float *bp = J->Bp + (size_t)p * n * NR + (size_t)k0 * NR;
            for (int i = i0; i < i1; i += MR) {
                int mr = i1 - i < MR ? i1 - i : MR;
                kernel(J->A + (size_t)i * n + k0, n, mr, bp,
                       J->C + (size_t)i * n + j0, n, kc, k0 == 0, nc);
            }
        }
    }
}

static void *worker_pack(void *arg)
{
    job_t *J = arg;
    int p;
    while ((p = __atomic_fetch_add(&J->next_pack, 1, __ATOMIC_RELAXED)) < J->npanels)
        pack_panel(J, p);
    return NULL;
}

static void *worker_mul(void *arg)
{
    job_t *J = arg;
    int c;
    while ((c = __atomic_fetch_add(&J->next_chunk, 1, __ATOMIC_RELAXED)) < J->nchunks)
        do_chunk(J, c);
    return NULL;
}

static void run(void *(*fn)(void *), job_t *J, int nt)
{
    pthread_t th[64];
    int started = 0;
    for (int t = 1; t < nt; t++)
        if (pthread_create(&th[started], NULL, fn, J) == 0) started++;
    fn(J);
    for (int t = 0; t < started; t++) pthread_join(th[t], NULL);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    job_t J;
    J.A = A; J.B = B; J.C = C; J.n = n;
    J.npanels = (n + NR - 1) / NR;
    J.nchunks = (n + MCHUNK - 1) / MCHUNK;
    J.next_pack = 0; J.next_chunk = 0;
    J.Bp = malloc((size_t)J.npanels * n * NR * sizeof(float));
    if (!J.Bp) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                float s = 0;
                for (int k = 0; k < n; k++) s += A[(size_t)i * n + k] * B[(size_t)k * n + j];
                C[(size_t)i * n + j] = s;
            }
        return;
    }
    long nc = sysconf(_SC_NPROCESSORS_ONLN);
    int nt = nc < 1 ? 1 : nc > 64 ? 64 : (int)nc;
    if ((double)n * n * n < 2e6) nt = 1;
    if (nt > J.nchunks) nt = J.nchunks;
    run(worker_pack, &J, nt);
    run(worker_mul, &J, nt);
    free(J.Bp);
}
